select extensions.ok(not has_table_privilege('authenticated','public.professional_availability_exceptions','DELETE') and not has_table_privilege('anon','public.professional_availability_exceptions','DELETE'),'professional_availability_exceptions no client DELETE grant');
select extensions.ok(not has_table_privilege('authenticated','public.clinical_change_events','SELECT') and not has_table_privilege('anon','public.clinical_change_events','SELECT'),'raw snapshot SELECT revoked');
select extensions.ok(not exists(select 1 from pg_proc where pronamespace='public'::regnamespace and proname in ('update_appointment_metadata_for_current_user','mutate_appointment_lifecycle_for_current_user','save_initial_clinical_history','save_professional_availability_for_current_user','manage_professional_availability_exception','set_patient_professional_assignment_for_current_user','get_review_invitation_status_for_current_user') and (not prosecdef or not proconfig @> array['search_path=public, pg_temp'] or has_function_privilege('anon',oid,'execute'))),'all hardened RPCs use fixed path and deny anon EXECUTE');
select * from extensions.finish();
rollback;
